// 这与我们的 `models.status='deprecated'`（合并退役）是两套语义，不可混用：
// 上游弃用说的是「厂商不再维护」，我们弃用说的是「这条已经并到别人身上」。
func (q *Queries) ListCatalogItems(ctx context.Context, arg ListCatalogItemsParams) ([]ListCatalogItemsRow, error) {
	rows, err := q.db.Query(ctx, listCatalogItems,
		arg.Q,
		arg.IncludeDeprecated,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCatalogItemsRow{}
	for rows.Next() {
		var i ListCatalogItemsRow
		if err := rows.Scan(
			&i.ID,
			&i.ProviderID,
			&i.ProviderName,
			&i.ExternalID,
			&i.Name,
			&i.CanonicalID,
			&i.VendorSlug,
			&i.Family,
			&i.ModelType,
			&i.UpstreamStatus,
			&i.ContextWindow,
			&i.MaxOutput,
			&i.CostIn,
			&i.CostOut,
			&i.ReleaseDate,
			&i.KnowledgeCutoff,
			&i.ModalitiesIn,
			&i.ModalitiesOut,
			&i.Description,
			&i.FetchedAt,
			&i.Imported,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

