const listModels = `-- name: ListModels :many

SELECT m.id,
       m.slug,
       m.name,
       COALESCE(m.vendor, '')::text AS vendor,
       m.status,
       m.resolution,
       COALESCE(t.slug, '')::text AS merged_into_slug,
       CASE
           WHEN EXISTS (SELECT 1 FROM model_external_refs r WHERE r.model_id = m.id) THEN 'models.dev'
           ELSE 'manual'
       END::text AS source,
       m.description,
       m.created_at,
       m.updated_at
FROM models m
LEFT JOIN models t ON t.id = m.merged_into_id
WHERE $1::text IS NULL OR m.status = $1::text
ORDER BY m.name, m.id
`

type ListModelsRow struct {
	ID             int64
	Slug           string
	Name           string
	Vendor         string
	Status         string
	Resolution     string
	MergedIntoSlug string
	Source         string
	Description    string
	CreatedAt      pgtype.Timestamptz
	UpdatedAt      pgtype.Timestamptz
}

// 模型维度的查询。
//
// 为什么单独一个文件：`db/queries/` 原来只有 authz/blob/demos/identity/review/settings/
// verification 七个——模型域有 15 张表，却一条 SQL 都没有。详情页要展示「这个作品用了
// 哪些模型」，靠的就是这里的四个查询。
// 模型目录：**全部状态**，可以按 status 筛，也可以不筛。
//
// 早先这里写死 `WHERE status = 'active'`，于是契约里的 `status` 字段永远是同一个值——
// 那等于没给。把筛选交给调用方（`?status=candidate`），字段才有意义。
//
// `source` 是派生的，不是列：`models` 表没有这一列，「这个模型是不是被上游目录认领过」
// 本来就是 `model_external_refs` 的事实。多加一列等于给同一件事两个出处。
//
// `merged_into_slug` 而不是 `merged_into_id`：合并归宿要用 slug 表达（引用一律 slug），
// 数字 id 是实现细节。
func (q *Queries) ListModels(ctx context.Context, status pgtype.Text) ([]ListModelsRow, error) {
	rows, err := q.db.Query(ctx, listModels, status)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListModelsRow{}
	for rows.Next() {
		var i ListModelsRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.Vendor,
			&i.Status,
			&i.Resolution,
			&i.MergedIntoSlug,
			&i.Source,
			&i.Description,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

